import{z as s,x as o,o as A,c as D,q as t,j as i,D as a,d as B,s as n,S as r,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"合成数据工程收束","description":"","frontmatter":{"title":"合成数据工程收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-engineering-map.md","filePath":"llm/synthetic-engineering-map.md","lastUpdated":1791413859000}'),d={name:"llm/synthetic-engineering-map.md"};function m(p,E,h,F,c,f){const l=o("Mermaid");return A(),D("div",null,[E[2]||(E[2]=t('<h1 id="合成数据工程收束" tabindex="-1">合成数据工程收束 <a class="header-anchor" href="#合成数据工程收束" aria-label="Permalink to &quot;合成数据工程收束&quot;">​</a></h1><div class="epigraph"><p>生成越来越便宜，稀缺的从来不是数据：是验证、覆盖审计，和那一份不许被挤掉的真实锚点。</p><footer>—— 据本课程十五课整理，口径与各课出处一致</footer></div><p><a href="/llm/synthetic-license-compliance">上一课</a>把合规做成管线的最后一道门。本课程到此收束：从<a href="/llm/synthetic-taxonomy">谱系分类</a>起步，经质量控制、域合成、配方与验证，到缩放与合规——本课把十五课拼回一条完整生产线，给出每站的控制点、跨站共享的失败模式，以及这门工程与相邻课程的接口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>十五课散开后容易丢掉整体：单站最优的组合未必是好的生产线——过滤器过严配合配比过松，等于用高成本买回原分布；难度窗收紧配合覆盖审计缺位，就是难度达标而题型塌缩；蒸馏数据与自合成混记一本账，两条上限互相掩盖。收束要回答的是：这条线的骨架是什么，站在哪里能看见哪类失败，新批次上线前最少要过几问。<span class="marginnote">直觉类比：生产线像足球队，十一个球星未必踢赢一支配合好的队伍——过滤器过严（堆了最强后卫）配配比过松（前锋没人补位），等于用高成本买回原分布。跨站看账，是这门工程区别于单点调优的地方。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生产线的九站与控制点。原料站：种子与真实锚点，控血统与覆盖的上限。生成站：无源、有源、程序三线，控变异方向与放量的边际。验证站：程序真值、裁判、无验证三档，控拦截率——它是全线的汇率中枢。过滤站：启发式、分类器、打分器加一致性三查，控投影方向。去重去污站：四层去重加生成器隔离，控重复燃料与泄漏。难度站：通过率分箱与课程序列加重标，控梯度密度。多样性站：四层度量加网格覆盖，控坍缩的先行指标。配比站：域、阶段、教师三粒度加末段退火，控份额。合规站：四链五门加台账，控合法性。评测集与消融协议是横切的两个基建：一把可信的尺，一套归因的协议，两个都不属于任何单站。</p>',7)),(A(),i(r,null,{default:a(()=>[n(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E5%8E%9F%E6%96%99%EF%BC%9A%E7%A7%8D%E5%AD%90%E4%B8%8E%E7%9C%9F%E5%AE%9E%E9%94%9A%E7%82%B9%22%5D%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%EF%BC%9A%E4%B8%89%E7%BA%BF%22%5D%0A%20%20GEN%20--%3E%20VER%5B%22%E9%AA%8C%E8%AF%81%EF%BC%9A%E6%8B%A6%E6%88%AA%E7%8E%87%E4%B8%AD%E6%9E%A2%22%5D%0A%20%20VER%20--%3E%20FIL%5B%22%E8%BF%87%E6%BB%A4%E4%B8%8E%E4%B8%80%E8%87%B4%E6%80%A7%22%5D%0A%20%20FIL%20--%3E%20DED%5B%22%E5%8E%BB%E9%87%8D%E4%B8%8E%E5%8E%BB%E6%B1%A1%22%5D%0A%20%20DED%20--%3E%20DIF%5B%22%E9%9A%BE%E5%BA%A6%EF%BC%9A%E9%80%9A%E8%BF%87%E7%8E%87%E5%88%86%E7%AE%B1%22%5D%0A%20%20DIF%20--%3E%20DIV%5B%22%E5%A4%9A%E6%A0%B7%E6%80%A7%EF%BC%9A%E7%BD%91%E6%A0%BC%E8%A6%86%E7%9B%96%22%5D%0A%20%20DIV%20--%3E%20MIX%5B%22%E9%85%8D%E6%AF%94%E4%B8%8E%E9%80%80%E7%81%AB%22%5D%0A%20%20MIX%20--%3E%20COMP%5B%22%E5%90%88%E8%A7%84%E4%BA%94%E9%97%A8%E4%B8%8E%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20EVAL%5B%22%E6%A8%AA%E5%88%87%EF%BC%9A%E5%90%88%E6%88%90%E8%AF%84%E6%B5%8B%E9%9B%86%22%5D%20--%3E%20MIX%0A%20%20ABL%5B%22%E6%A8%AA%E5%88%87%EF%BC%9A%E6%B6%88%E8%9E%8D%E5%8D%8F%E8%AE%AE%22%5D%20--%3E%20MIX%0A%20%20COMP%20--%3E%20REL%5B%22%E5%8F%91%E5%B8%83%EF%BC%9A%E5%8D%A0%E6%AF%94%E4%B8%8E%E8%A1%80%E7%BB%9F%E5%A3%B0%E6%98%8E%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"跨站共享的失败模式有三条主轴。选择压力轴：过滤器、fitness、成功率、难度窗全都在选择样本；选择叠加而不留通道，分布就系统性漂移——解药是有意回混：真实题、失败样本、窗外难题都要留份额。同源轴：生成器、打分器、用户模拟器、评测生成器若同源，偏置相互放大且不可见——解药是分离：生成与打分分离，训练与评测隔离，教师与学生分版本记账。反馈延迟轴：合成管线的错误大多不在当轮显形（日志更好看、分更高），而在下游或数代后显形——解药是把先行指标挂在前：held-out 真题边际增量、生成熵、新颖占比、回退率，任何一个掉头都先于质量崩塌。",-1)),(A(),i(r,null,{default:a(()=>[n(l,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20LR%0A%20%20A1%5B%22%E9%80%89%E6%8B%A9%E5%8E%8B%E5%8A%9B%E8%BD%B4%3A%20%E5%A4%9A%E5%B1%82%E8%BF%87%E6%BB%A4%E5%8F%A0%E5%8A%A0%22%5D%20--%3E%20D1%5B%22%E5%88%86%E5%B8%83%E7%B3%BB%E7%BB%9F%E6%80%A7%E6%BC%82%E7%A7%BB%22%5D%0A%20%20D1%20--%3E%20R1%5B%22%E8%A7%A3%E8%8D%AF%3A%20%E5%9B%9E%E6%B7%B7%E7%9C%9F%E5%AE%9E%E9%A2%98%2F%E5%A4%B1%E8%B4%A5%E6%A0%B7%E6%9C%AC%2F%E7%AA%97%E5%A4%96%E9%9A%BE%E9%A2%98%22%5D%0A%20%20A2%5B%22%E5%90%8C%E6%BA%90%E8%BD%B4%3A%20%E7%94%9F%E6%88%90%E4%B8%8E%E6%89%93%E5%88%86%E5%90%8C%E6%BA%90%22%5D%20--%3E%20D2%5B%22%E5%81%8F%E7%BD%AE%E7%9B%B8%E4%BA%92%E6%94%BE%E5%A4%A7%E4%B8%94%E4%B8%8D%E5%8F%AF%E8%A7%81%22%5D%0A%20%20D2%20--%3E%20R2%5B%22%E8%A7%A3%E8%8D%AF%3A%20%E7%94%9F%E6%88%90%E4%B8%8E%E6%89%93%E5%88%86%E5%88%86%E7%A6%BB%2C%20%E8%AE%AD%E7%BB%83%E4%B8%8E%E8%AF%84%E6%B5%8B%E9%9A%94%E7%A6%BB%22%5D%0A%20%20A3%5B%22%E5%8F%8D%E9%A6%88%E5%BB%B6%E8%BF%9F%E8%BD%B4%3A%20%E9%94%99%E8%AF%AF%E6%95%B0%E4%BB%A3%E5%90%8E%E6%89%8D%E6%98%BE%E5%BD%A2%22%5D%20--%3E%20D3%5B%22%E6%97%A5%E5%BF%97%E6%9B%B4%E5%A5%BD%E7%9C%8B%2C%20%E4%B8%8B%E6%B8%B8%E5%B7%B2%E5%9D%8F%22%5D%0A%20%20D3%20--%3E%20R3%5B%22%E8%A7%A3%E8%8D%AF%3A%20%E5%85%88%E8%A1%8C%E6%8C%87%E6%A0%87%E6%8C%82%E5%9C%A8%E5%89%8D%2C%20%E6%8E%89%E5%A4%B4%E5%8D%B3%E5%81%9C%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">常见误区：初学者容易把「本轮日志更好看、评测分更高」当成管线健康的证据。合成管线的错误大多延迟显形——真正的先行指标是 held-out 真题边际增量、生成熵、新颖占比，任何一个掉头都比分数掉头早好几代。</span></p><p><span class="marginnote">新批次上线五问：来源可溯吗？验证器可信且与用途匹配吗？去重去污版本对齐吗？难度与多样性的读数在窗内吗？真实探针的边际增量为正吗？有否定，批次不进配比——这门工程的全部纪律，浓缩起来就是让这五问在每一批都真的被问过。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程写的是数据侧工程；模型侧的对应物各有专课：蒸馏的机制与失真在<a href="/llm/cot-distill">推理链蒸馏</a>与<a href="/llm/reasoning-distill-small">推理蒸馏到小模型</a>，自训练回路的收益与损耗在<a href="/llm/self-improvement-loop">自改进回路的解剖</a>与<a href="/llm/data-flywheel-stop">数据飞轮的停止条件</a>，闭环的极限后果在<a href="/llm/model-collapse-empirics">模型坍缩的实证</a>。方法的有效期绑定教师与基座版本：换代之后，能继承的是骨架——五元组、三轴、九站，不是参数。最后要承认这门学科的边界：验证器覆盖不到的地方——品味、安全、开放域价值——合成数据只有代理信号，那里的问题要交给偏好数据与对齐评测的工程，不是本课程的能力范围。<span class="marginnote">为什么重要：换了教师模型，拦截率、难度窗、配比的最优值全部重排，能继承的只有骨架（五元组、三轴、九站）。把旧参数当经验带进新项目，是新团队最常犯的迁移错误——参数随版本作废，骨架才可继承。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>生产线九站加两个横切基建；验证站是全线汇率中枢。</li><li>三条失败主轴：选择压力、同源偏置、反馈延迟；解药分别是回混、分离、先行指标。</li><li>新批次五问是最低验收线，否定即不进配比。</li><li>合成的稀缺资源是验证、覆盖审计与真实锚点，不是生成量。</li><li>本课程到此收束：骨架可继承，参数随版本作废。</li><li>出处：本课程总口径——Self-Instruct、Evol-Instruct、Textbooks、Meta-Math、RFT、Lightman PRM、Magicoder、CAMEL、UltraChat、Toolformer、ReST、s1、R1、Muennighoff 2024、Shumailov 2024、The Stack v2、LIMA、DEITA、Dynabench、LiveBench。</li></ul>',6))])}const _=s(d,[["render",m]]);export{u as __pageData,_ as default};
